#!/usr/bin/env python3
"""Clean-room reimplementation of the keifu terminal UI.

This program intentionally depends only on Python's standard library and the
`git` command-line tool.  It implements the documented/user-observable keifu
behavior: a no-argument clap-like CLI, a Unicode commit graph TUI, commit detail
and changed-file panels, branch search, basic branch operations, and fetch.
"""
from __future__ import annotations

import errno
import os
import re
import select
import shutil
import signal
import subprocess
import sys
import termios
import textwrap
import time
import tty
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple

US = "\x1f"
EMPTY_TREE = "4b825dc642cb6eb9a060e54bf8d69288fbee4904"
VERSION = "keifu 0.2.3"
HELP_TEXT = """A TUI tool to visualize Git commit graphs with branch genealogy

Usage: executable

Options:
  -h, --help     Print help
  -V, --version  Print version"""


# ----------------------------- small utilities -----------------------------

def eprint(text: str = "") -> None:
    print(text, file=sys.stderr)


def run_git(args: List[str], cwd: Optional[str] = None, check: bool = False,
            timeout: Optional[float] = None) -> subprocess.CompletedProcess:
    env = os.environ.copy()
    env.setdefault("GIT_PAGER", "cat")
    env.setdefault("PAGER", "cat")
    return subprocess.run(
        ["git"] + args,
        cwd=cwd,
        env=env,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=check,
        timeout=timeout,
    )


def git_out(args: List[str], cwd: Optional[str] = None) -> str:
    cp = run_git(args, cwd=cwd)
    if cp.returncode != 0:
        return ""
    return cp.stdout.rstrip("\n")


def first_error_line(stderr: str) -> str:
    for line in stderr.splitlines():
        line = line.strip()
        if line:
            return line
    return ""


def trunc(s: str, width: int) -> str:
    if width <= 0:
        return ""
    if len(s) <= width:
        return s
    return s[:width]


def pad(s: str, width: int) -> str:
    if width <= 0:
        return ""
    s = trunc(s, width)
    return s + " " * (width - len(s))


def center_pos(total: int, size: int) -> int:
    return max(0, (total - size) // 2)


def safe_int(s: str, default: int) -> int:
    try:
        return int(s)
    except Exception:
        return default


# ----------------------------- CLI / config --------------------------------

def print_unexpected_arg(arg: str) -> int:
    eprint(f"error: unexpected argument '{arg}' found")
    eprint()
    eprint("Usage: executable")
    eprint()
    eprint("For more information, try '--help'.")
    return 2


def parse_cli(argv: List[str]) -> Optional[int]:
    if not argv:
        return None
    first = argv[0]
    if first == "--":
        if len(argv) == 1:
            return None
        return print_unexpected_arg(argv[1])
    if first.startswith("--help="):
        val = first.split("=", 1)[1]
        eprint(f"error: unexpected value '{val}' for '--help' found; no more were expected")
        eprint()
        eprint("Usage: executable --help")
        eprint()
        eprint("For more information, try '--help'.")
        return 2
    if first.startswith("--version="):
        val = first.split("=", 1)[1]
        eprint(f"error: unexpected value '{val}' for '--version' found; no more were expected")
        eprint()
        eprint("Usage: executable --version")
        eprint()
        eprint("For more information, try '--help'.")
        return 2
    if first in ("-h", "--help") or (first.startswith("-") and first != "-" and "h" in first[1:] and not first.startswith("--")):
        print(HELP_TEXT)
        return 0
    if first in ("-V", "--version") or (first.startswith("-") and first != "-" and "V" in first[1:] and not first.startswith("--")):
        print(VERSION)
        return 0
    return print_unexpected_arg(first)


@dataclass
class RefreshConfig:
    auto_refresh: bool = True
    refresh_interval: int = 10
    auto_fetch: bool = True
    fetch_interval: int = 60


def parse_bool(v: str, default: bool) -> bool:
    t = v.strip().lower()
    if t in ("true", "1", "yes", "on"):
        return True
    if t in ("false", "0", "no", "off"):
        return False
    return default


def load_config() -> RefreshConfig:
    cfg = RefreshConfig()
    path = os.path.expanduser("~/.config/keifu/config.toml")
    if not os.path.exists(path):
        return cfg
    section = ""
    try:
        with open(path, "r", encoding="utf-8") as f:
            for raw in f:
                line = raw.split("#", 1)[0].strip()
                if not line:
                    continue
                if line.startswith("[") and line.endswith("]"):
                    section = line[1:-1].strip()
                    continue
                if section != "refresh" or "=" not in line:
                    continue
                key, val = [x.strip() for x in line.split("=", 1)]
                if key == "auto_refresh":
                    cfg.auto_refresh = parse_bool(val, cfg.auto_refresh)
                elif key == "auto_fetch":
                    cfg.auto_fetch = parse_bool(val, cfg.auto_fetch)
                elif key == "refresh_interval":
                    cfg.refresh_interval = max(1, safe_int(val, cfg.refresh_interval))
                elif key == "fetch_interval":
                    cfg.fetch_interval = max(10, safe_int(val, cfg.fetch_interval))
    except Exception:
        pass
    return cfg


# ----------------------------- data model ----------------------------------

@dataclass
class Label:
    display: str
    kind: str                  # local, tracking, remote
    commit: str
    local: Optional[str] = None
    remote: Optional[str] = None


@dataclass
class DisplayRow:
    kind: str                  # commit, connector, uncommitted
    graph: str = ""
    commit: Optional[str] = None
    subject: str = ""
    author: str = ""
    email: str = ""
    date: str = ""
    parents: List[str] = field(default_factory=list)
    file_count: int = 0        # for uncommitted


@dataclass
class FileChange:
    status: str
    path: str
    added: Optional[int] = None
    deleted: Optional[int] = None


@dataclass
class RepoData:
    root: str
    repo_name: str
    current_branch: str = ""
    head_hash: Optional[str] = None
    rows: List[DisplayRow] = field(default_factory=list)
    selectable_rows: List[int] = field(default_factory=list)
    labels_by_commit: Dict[str, List[Label]] = field(default_factory=dict)
    local_branches: Dict[str, str] = field(default_factory=dict)
    remote_branches: Dict[str, str] = field(default_factory=dict)
    uncommitted_count: int = 0


@dataclass
class AppState:
    data: RepoData
    selection: int = 0              # index into selectable_rows
    scroll: int = 0                 # display-row offset inside commit pane
    label_indices: Dict[str, int] = field(default_factory=dict)
    mode: str = "normal"           # normal, help, input_branch, search, confirm_delete, error
    input_text: str = ""
    search_results: List[Label] = field(default_factory=list)
    search_selected: int = 0
    confirm_branch: str = ""
    status_message: str = ""
    status_error: bool = False
    last_refresh: float = field(default_factory=time.time)
    last_fetch: float = field(default_factory=time.time)


# ----------------------------- repository loading ---------------------------

def find_repo_root() -> Optional[str]:
    cp = run_git(["rev-parse", "--show-toplevel"])
    if cp.returncode == 0:
        return cp.stdout.strip()
    # Bare repos do not have a worktree, but the original is primarily a
    # worktree UI.  Still, accept a git-dir if it is present.
    cp = run_git(["rev-parse", "--git-dir"])
    if cp.returncode == 0:
        return os.getcwd()
    return None


def print_not_repo_error() -> None:
    eprint("Error: Git repository not found. Please run inside a Git repository.")
    eprint()
    eprint("Caused by:")
    eprint("    could not find repository at '.'; class=Repository (6); code=NotFound (-3)")


def has_head(root: str) -> Optional[str]:
    cp = run_git(["rev-parse", "--verify", "HEAD"], cwd=root)
    if cp.returncode != 0:
        return None
    return cp.stdout.strip()


def load_refs(root: str, current_branch: str) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str], Dict[str, List[Label]]]:
    local: Dict[str, str] = {}
    upstream: Dict[str, str] = {}
    remote: Dict[str, str] = {}
    labels_by_commit: Dict[str, List[Label]] = {}

    cp = run_git(["for-each-ref", "--format=%(refname:short)%00%(objectname)%00%(upstream:short)", "refs/heads"], cwd=root)
    if cp.returncode == 0:
        for line in cp.stdout.splitlines():
            parts = line.split("\x00")
            if len(parts) >= 2 and parts[0] and parts[1]:
                local[parts[0]] = parts[1]
                if len(parts) >= 3 and parts[2]:
                    upstream[parts[0]] = parts[2]

    cp = run_git(["for-each-ref", "--format=%(refname:short)%00%(objectname)", "refs/remotes"], cwd=root)
    if cp.returncode == 0:
        for line in cp.stdout.splitlines():
            parts = line.split("\x00")
            if len(parts) >= 2 and parts[0] and parts[1]:
                if parts[0].endswith("/HEAD"):
                    continue
                remote[parts[0]] = parts[1]

    consumed_remotes = set()

    def add_label(label: Label) -> None:
        labels_by_commit.setdefault(label.commit, []).append(label)

    # Current branch first, then other local branches alphabetically.
    local_names = sorted(local)
    if current_branch in local_names:
        local_names.remove(current_branch)
        local_names.insert(0, current_branch)

    for name in local_names:
        commit = local[name]
        up = upstream.get(name, "")
        if up and remote.get(up) == commit:
            remote_name = up.split("/", 1)[0]
            add_label(Label(f"{name} ↔ {remote_name}", "tracking", commit, local=name, remote=up))
            consumed_remotes.add(up)
        else:
            add_label(Label(name, "local", commit, local=name))

    for name in sorted(remote):
        if name in consumed_remotes:
            continue
        add_label(Label(name, "remote", remote[name], local=name.split("/", 1)[-1], remote=name))

    return local, remote, upstream, labels_by_commit


def transform_connector(raw: str) -> str:
    s = raw.rstrip()
    if not s:
        return ""
    # Common git graph connector rows, made to look like the observed Unicode UI.
    s = s.replace("|/", "├─╯")
    s = s.replace("|\\", "├─╮")
    trans = []
    for ch in s:
        trans.append({"|": "│", "/": "╯", "\\": "╮", "-": "─", "_": "─"}.get(ch, ch))
    return "".join(trans)


def transform_commit_graph(raw: str, symbol: str) -> str:
    s = raw.rstrip()
    if "*" in s:
        idx = s.rfind("*")
        s = s[:idx] + symbol + s[idx + 1:]
    else:
        s = symbol
    trans = []
    for ch in s:
        trans.append({"|": "│", "/": "╯", "\\": "╮", "-": "─", "_": "─"}.get(ch, ch))
    return "".join(trans)


def parse_git_graph(root: str, head_hash: Optional[str], labels_by_commit: Dict[str, List[Label]]) -> List[DisplayRow]:
    if not head_hash:
        return []
    fmt = "%H%x1f%P%x1f%an%x1f%ae%x1f%ad%x1f%s"
    cp = run_git([
        "log", "--graph", "--date-order", "--max-count=500",
        f"--pretty=format:{fmt}", "--date=format:%Y-%m-%d %H:%M:%S",
        "HEAD", "--all",
    ], cwd=root)
    if cp.returncode != 0 or not cp.stdout:
        return []

    lines = cp.stdout.splitlines()
    parsed: List[Tuple[str, Optional[List[str]]]] = []
    cre = re.compile(r"^(.*?)([0-9a-f]{40})\x1f(.*)$")
    i = 0
    while i < len(lines):
        line = lines[i]
        m = cre.match(line)
        if not m:
            parsed.append((line, None))
            i += 1
            continue
        graph_raw, commit, rest = m.group(1), m.group(2), m.group(3)
        # Fold the immediate merge connector row into the merge commit row,
        # matching the observed "●─╮" style.
        extra_merge = False
        if i + 1 < len(lines) and not cre.match(lines[i + 1]) and "|\\" in lines[i + 1]:
            extra_merge = True
            i += 1
        parsed.append((graph_raw + (" __MERGE__" if extra_merge else ""), [commit] + rest.split(US)))
        i += 1

    rows: List[DisplayRow] = []
    for graph_raw, fields in parsed:
        if fields is None:
            g = transform_connector(graph_raw)
            if g:
                rows.append(DisplayRow("connector", graph=g))
            continue
        commit = fields[0]
        parents = fields[1].split() if len(fields) > 1 and fields[1] else []
        author = fields[2] if len(fields) > 2 else ""
        email = fields[3] if len(fields) > 3 else ""
        date = fields[4] if len(fields) > 4 else ""
        subject = fields[5] if len(fields) > 5 else ""
        merge = False
        if graph_raw.endswith(" __MERGE__"):
            merge = True
            graph_raw = graph_raw[:-10]
        sym = "◉" if commit == head_hash else "●"
        g = transform_commit_graph(graph_raw, sym)
        if merge:
            # If the graph is just "◉"/"●", make it "◉─╮"/"●─╮"; if it has
            # leading columns, append the branch arc at the commit position.
            g = g.rstrip() + "─╮"
        rows.append(DisplayRow("commit", graph=g, commit=commit, subject=subject,
                               author=author, email=email, date=date, parents=parents))
    return rows


def load_uncommitted(root: str, head_hash: Optional[str]) -> int:
    if not head_hash:
        return 0
    changes, _, _ = get_file_changes(root, None, uncommitted=True)
    return len(changes)


def load_repo(root: str) -> RepoData:
    repo_name = os.path.basename(root.rstrip(os.sep)) or root
    head = has_head(root)
    current = git_out(["branch", "--show-current"], cwd=root).strip() if head else ""
    if head and not current:
        current = "HEAD"
    local, remote, upstream, labels = load_refs(root, current if current != "HEAD" else "")
    rows = parse_git_graph(root, head, labels)
    uncommitted = load_uncommitted(root, head)
    if uncommitted:
        rows.insert(0, DisplayRow("uncommitted", graph="●", subject=f"uncommitted changes ({uncommitted})", file_count=uncommitted))
    selectable = [i for i, r in enumerate(rows) if r.kind in ("commit", "uncommitted")]
    return RepoData(root=root, repo_name=repo_name, current_branch=current, head_hash=head,
                    rows=rows, selectable_rows=selectable, labels_by_commit=labels,
                    local_branches=local, remote_branches=remote, uncommitted_count=uncommitted)


# ----------------------------- changed-file stats ---------------------------

def diff_base_for_commit(root: str, commit: str) -> Tuple[str, str, List[str]]:
    cp = run_git(["rev-list", "--parents", "-n", "1", commit], cwd=root)
    if cp.returncode != 0:
        return EMPTY_TREE, commit, []
    parts = cp.stdout.strip().split()
    parents = parts[1:]
    old = parents[0] if parents else EMPTY_TREE
    return old, commit, parents


def parse_name_status(stdout: str) -> List[Tuple[str, str]]:
    out: List[Tuple[str, str]] = []
    for line in stdout.splitlines():
        if not line:
            continue
        parts = line.split("\t")
        if not parts:
            continue
        status = parts[0]
        # With --no-renames this is normally one path; be defensive for copies.
        path = parts[-1] if len(parts) > 1 else ""
        out.append((status[:1], path))
    return out


def parse_numstat(stdout: str) -> Dict[str, Tuple[Optional[int], Optional[int]]]:
    out: Dict[str, Tuple[Optional[int], Optional[int]]] = {}
    for line in stdout.splitlines():
        parts = line.split("\t")
        if len(parts) < 3:
            continue
        a, d, path = parts[0], parts[1], parts[2]
        if a == "-" or d == "-":
            out[path] = (None, None)
        else:
            out[path] = (safe_int(a, 0), safe_int(d, 0))
    return out


def get_file_changes(root: str, commit: Optional[str], uncommitted: bool = False) -> Tuple[List[FileChange], int, int]:
    if uncommitted:
        # git diff HEAD includes staged + unstaged tracked changes and staged
        # new files, while ignoring untracked files, matching the docs.
        ns = run_git(["diff", "--no-renames", "--name-status", "HEAD", "--"], cwd=root)
        num = run_git(["diff", "--no-renames", "--numstat", "HEAD", "--"], cwd=root)
    else:
        if not commit:
            return [], 0, 0
        old, new, _parents = diff_base_for_commit(root, commit)
        ns = run_git(["diff", "--no-renames", "--name-status", old, new, "--"], cwd=root)
        num = run_git(["diff", "--no-renames", "--numstat", old, new, "--"], cwd=root)
    statuses = parse_name_status(ns.stdout if ns.returncode == 0 else "")
    nums = parse_numstat(num.stdout if num.returncode == 0 else "")
    changes: List[FileChange] = []
    total_a = 0
    total_d = 0
    for st, path in statuses:
        a, d = nums.get(path, (None, None))
        if a is not None:
            total_a += a
        if d is not None:
            total_d += d
        changes.append(FileChange(st, path, a, d))
    changes.sort(key=lambda c: c.path)
    return changes[:50], total_a, total_d


def full_commit_message(root: str, commit: str) -> str:
    cp = run_git(["log", "-1", "--format=%B", commit], cwd=root)
    if cp.returncode != 0:
        return ""
    return cp.stdout.rstrip("\n")


# ----------------------------- rendering -----------------------------------

def box(width: int, height: int, title: str, content_lines: List[str], wrap: bool = False) -> List[str]:
    width = max(2, width)
    height = max(2, height)
    inner = max(0, width - 2)
    title_text = f" {title} " if title else ""
    if len(title_text) > inner:
        title_text = title_text[:inner]
    top = "┌" + title_text + "─" * max(0, inner - len(title_text)) + "┐"
    bottom = "└" + "─" * inner + "┘"
    prepared: List[str] = []
    if wrap:
        for line in content_lines:
            if line == "":
                prepared.append("")
            else:
                w = max(1, inner)
                parts = textwrap.wrap(line, width=w, replace_whitespace=False,
                                      drop_whitespace=True, break_long_words=True,
                                      break_on_hyphens=False)
                prepared.extend(parts or [""])
    else:
        prepared = content_lines[:]
    body = []
    for i in range(height - 2):
        s = prepared[i] if i < len(prepared) else ""
        body.append("│" + pad(s, inner) + "│")
    return [top] + body + [bottom]


def overlay(screen: List[List[str]], x: int, y: int, lines: List[str]) -> None:
    h = len(screen)
    w = len(screen[0]) if h else 0
    for dy, line in enumerate(lines):
        yy = y + dy
        if yy < 0 or yy >= h:
            continue
        for dx, ch in enumerate(line):
            xx = x + dx
            if 0 <= xx < w:
                screen[yy][xx] = ch


def current_selected_row(state: AppState) -> Optional[DisplayRow]:
    if not state.data.selectable_rows:
        return None
    state.selection = max(0, min(state.selection, len(state.data.selectable_rows) - 1))
    return state.data.rows[state.data.selectable_rows[state.selection]]


def selected_label(state: AppState, row: Optional[DisplayRow] = None) -> Optional[Label]:
    row = row or current_selected_row(state)
    if not row or row.kind != "commit" or not row.commit:
        return None
    labels = state.data.labels_by_commit.get(row.commit, [])
    if not labels:
        return None
    idx = state.label_indices.get(row.commit, 0)
    idx = max(0, min(idx, len(labels) - 1))
    state.label_indices[row.commit] = idx
    return labels[idx]


def graph_field_width(rows: List[DisplayRow]) -> int:
    if not rows:
        return 3
    m = max((len(r.graph.rstrip()) for r in rows), default=1)
    return max(3, m + 2)


def render_commit_line(state: AppState, row: DisplayRow, width: int, gwidth: int) -> str:
    inner = max(0, width - 2)
    graph = pad(row.graph.rstrip(), gwidth)
    if row.kind == "connector":
        return "│" + pad(" " + graph, inner) + "│"
    if row.kind == "uncommitted":
        text = graph + row.subject
        return "│" + pad(" " + text, inner) + "│"

    labels = state.data.labels_by_commit.get(row.commit or "", [])
    label_txt = ""
    if labels:
        idx = state.label_indices.get(row.commit or "", 0)
        idx = max(0, min(idx, len(labels) - 1))
        state.label_indices[row.commit or ""] = idx
        label_txt = f"[{labels[idx].display}]"
        if len(labels) > 1:
            label_txt += f" +{len(labels)-1}"
        label_txt += " "

    short = (row.commit or "")[:7]
    date10 = (row.date or "")[:10]
    author = pad(row.author[:8], 8)
    full_meta = f"{date10}  {author}  {short}" if row.commit else ""
    if inner < 45:
        meta = short
    elif inner < 62:
        meta = f"{date10}  {short}" if date10 else short
    else:
        meta = full_meta
    left = graph + label_txt
    reserve = len(meta) + (1 if meta else 0)
    msg_width = max(0, inner - 1 - len(left) - reserve)
    msg = trunc(row.subject, msg_width)
    content = " " + left + pad(msg, msg_width)
    if meta:
        content += " " + meta
    return "│" + pad(content, inner) + "│"


def ensure_scroll(state: AppState, inner_h: int) -> None:
    if not state.data.selectable_rows:
        state.scroll = 0
        return
    sel_row = state.data.selectable_rows[state.selection]
    if sel_row < state.scroll:
        state.scroll = sel_row
    elif sel_row >= state.scroll + inner_h:
        state.scroll = sel_row - inner_h + 1
    max_scroll = max(0, len(state.data.rows) - inner_h)
    state.scroll = max(0, min(state.scroll, max_scroll))


def render_commits(state: AppState, width: int, height: int) -> List[str]:
    inner_h = max(0, height - 2)
    ensure_scroll(state, inner_h)
    gwidth = graph_field_width(state.data.rows)
    visible: List[str] = []
    for i in range(inner_h):
        idx = state.scroll + i
        if idx < len(state.data.rows):
            visible.append(render_commit_line(state, state.data.rows[idx], width, gwidth))
        else:
            visible.append("│" + " " * max(0, width - 2) + "│")
    top = box(width, 2, "Commits", [])[0]
    bottom = "└" + "─" * max(0, width - 2) + "┘"
    return [top] + visible + [bottom]


def render_detail_lines(state: AppState) -> Tuple[List[str], List[str]]:
    row = current_selected_row(state)
    if row is None:
        return ["Select a commit"], []
    if row.kind == "uncommitted":
        changes, add, dele = get_file_changes(state.data.root, None, uncommitted=True)
        left = ["Uncommitted Changes", "", f"{len(changes)} files with changes"]
        right = [f"{len(changes)} files changed  +{add} -{dele}", ""]
        for ch in changes:
            stats = "" if ch.added is None else f" +{ch.added} -{ch.deleted}"
            right.append(f" {ch.status} {ch.path}{stats}")
        return left, right
    if row.kind != "commit" or not row.commit:
        return ["Select a commit"], []

    parents = row.parents
    left = [f"Commit: {row.commit}", f"Author: {row.author} <{row.email}>", f"Date:   {row.date}"]
    if parents:
        left.append("Parent: " + ", ".join(p[:7] for p in parents))
    left.append("")
    msg = full_commit_message(state.data.root, row.commit)
    if msg:
        left.extend(msg.splitlines())
    changes, add, dele = get_file_changes(state.data.root, row.commit, uncommitted=False)
    right = [f"{len(changes)} files changed  +{add} -{dele}", ""]
    for ch in changes:
        stats = "" if ch.added is None else f" +{ch.added} -{ch.deleted}"
        right.append(f" {ch.status} {ch.path}{stats}")
    return left, right


def render_details(state: AppState, width: int, height: int) -> List[str]:
    left_w = width // 2
    right_w = width - left_w
    left_lines, right_lines = render_detail_lines(state)
    left = box(left_w, height, "Commit Detail", left_lines, wrap=True)
    right = box(right_w, height, "Changed Files", right_lines, wrap=False)
    return [l + r for l, r in zip(left, right)]


def status_line(state: AppState, width: int) -> str:
    parts = [state.data.repo_name]
    if state.data.current_branch:
        parts.append(state.data.current_branch)
    mode_label = ""
    if state.mode == "help":
        parts.append("Esc/q close help")
        mode_label = "HELP"
    elif state.mode in ("input_branch", "search"):
        parts.append("Enter confirm  Esc cancel")
        mode_label = "INPUT"
    elif state.mode == "confirm_delete":
        parts.append("y yes  n no")
        mode_label = "CONFIRM"
    elif state.mode == "error" or state.status_error:
        if state.status_message:
            parts.append(state.status_message)
        parts.append("Esc/Enter close")
        mode_label = "ERROR"
    elif state.status_message:
        parts.append(state.status_message)
    else:
        parts.extend(["j/k move", "Enter checkout", "b branch", "f fetch", "? help", "q quit"])
    text = " " + "   ".join(parts)
    if mode_label:
        # Right-align the mode label when there is room.
        if len(text) + 1 + len(mode_label) <= width:
            text = text + " " * (width - len(text) - len(mode_label)) + mode_label
    return pad(text, width)


def branch_selector_overlay(state: AppState, screen: List[List[str]], width: int, commit_h: int) -> None:
    if state.mode != "normal":
        return
    row = current_selected_row(state)
    if not row or row.kind != "commit" or not row.commit:
        return
    labels = state.data.labels_by_commit.get(row.commit, [])
    if len(labels) <= 1:
        return
    idx = state.label_indices.get(row.commit, 0)
    names = [("▶ " if i == idx else "  ") + lab.display for i, lab in enumerate(labels)]
    w = min(max(12, max(len(n) for n in names) + 2), max(12, width - 4))
    h = min(len(names) + 2, commit_h - 2 if commit_h > 4 else len(names) + 2)
    lines = box(w, h, "Branches", names[:h-2], wrap=False)
    x = max(1, width - w - 2)
    y = 2
    overlay(screen, x, y, lines)


def modal_box(title: str, lines: List[str], width: int, height: Optional[int] = None) -> List[str]:
    if height is None:
        height = len(lines) + 2
    return box(width, height, title, lines, wrap=False)


def render_modal(state: AppState, screen: List[List[str]], width: int, height: int, commit_h: int, detail_h: int) -> None:
    if state.mode == "help":
        lines = [
            "Navigation",
            "  j / ↓      Move down",
            "  k / ↑      Move up",
            "  ] / Tab    Select next branch",
            "  [ / S-Tab  Select previous branch",
            "  h / ←      Select left branch (same commit)",
            "  l / →      Select right branch (same commit)",
            "  Ctrl+d     Page down",
            "  Ctrl+u     Page up",
            "  g / Home   Go to top",
            "  G / End    Go to bottom",
            "  @          Jump to HEAD (current branch)",
            "",
            "Git Operations",
            "  Enter      Checkout selected branch/commit",
            "  b          Create new branch",
            "  d          Delete branch",
            "  f          Fetch from origin",
        ]
        w = min(60, max(20, width - 4))
        h = min(22, max(8, height - 4), len(lines) + 2)
        overlay(screen, center_pos(width, w), center_pos(height, h), box(w, h, "Help", lines, wrap=False))
    elif state.mode == "input_branch":
        w = min(50, max(20, width - 4))
        lines = ["", "  " + trunc(state.input_text, w - 6) + "_", "", "  Enter: confirm  Esc: cancel"]
        h = 6
        y = max(1, center_pos(commit_h, h))
        overlay(screen, center_pos(width, w), y, box(w, h, "New Branch Name", lines, wrap=False))
    elif state.mode == "confirm_delete":
        w = min(50, max(24, width - 4))
        msg = f"  Delete branch '{state.confirm_branch}'?"
        lines = ["", msg, "", "  y: Yes  n: No"]
        h = 6
        y = max(1, center_pos(commit_h, h))
        overlay(screen, center_pos(width, w), y, box(w, h, "Confirm", lines, wrap=False))
    elif state.mode == "search":
        w = min(60, max(24, width - 4))
        if state.input_text:
            h = min(8, 4 + min(3, len(state.search_results)))
            content = ["  " + trunc(state.input_text, w - 6) + "_", "─" * max(0, w - 2)]
            max_results = max(0, h - 4)
            for i, lab in enumerate(state.search_results[:max_results]):
                prefix = "▶ " if i == state.search_selected else "  "
                content.append(prefix + lab.display)
            content.append("  ↑↓: select  Enter: jump  Esc: cancel")
        else:
            h = 4
            content = ["  _", "  Enter: confirm  Esc: cancel"]
        y = commit_h + max(0, center_pos(detail_h, h))
        overlay(screen, center_pos(width, w), y, box(w, h, "Search branches", content, wrap=False))


def render(state: AppState, term_w: int, term_h: int) -> str:
    width = max(20, term_w)
    height = max(6, term_h)
    detail_h = max(7, int(height * 0.30)) if height >= 12 else max(3, height // 3)
    detail_h = min(detail_h, max(2, height - 3))
    commit_h = max(2, height - detail_h - 1)

    lines = render_commits(state, width, commit_h) + render_details(state, width, detail_h)
    lines = lines[:height - 1]
    while len(lines) < height - 1:
        lines.append(" " * width)
    lines.append(status_line(state, width))
    screen = [list(pad(line, width)) for line in lines]
    branch_selector_overlay(state, screen, width, commit_h)
    render_modal(state, screen, width, height, commit_h, detail_h)
    return "\r\n".join("".join(row) for row in screen)


# ----------------------------- actions -------------------------------------

def reload_state(state: AppState) -> None:
    old_commit = None
    row = current_selected_row(state)
    if row and row.kind == "commit":
        old_commit = row.commit
    elif row and row.kind == "uncommitted":
        old_commit = "__uncommitted__"
    state.data = load_repo(state.data.root)
    # Preserve selection by commit where possible.
    if old_commit:
        for si, ri in enumerate(state.data.selectable_rows):
            r = state.data.rows[ri]
            if (old_commit == "__uncommitted__" and r.kind == "uncommitted") or r.commit == old_commit:
                state.selection = si
                break
        else:
            state.selection = min(state.selection, max(0, len(state.data.selectable_rows) - 1))
    else:
        state.selection = min(state.selection, max(0, len(state.data.selectable_rows) - 1))
    # Trim branch label indices.
    for commit, labels in list(state.data.labels_by_commit.items()):
        state.label_indices[commit] = max(0, min(state.label_indices.get(commit, 0), len(labels) - 1))


def set_error(state: AppState, message: str) -> None:
    state.status_message = message
    state.status_error = True
    state.mode = "error"


def clear_status(state: AppState) -> None:
    state.status_message = ""
    state.status_error = False
    if state.mode == "error":
        state.mode = "normal"


def move_selection(state: AppState, delta: int) -> None:
    if not state.data.selectable_rows:
        return
    state.selection = max(0, min(len(state.data.selectable_rows) - 1, state.selection + delta))


def jump_selection(state: AppState, to_end: bool = False) -> None:
    if not state.data.selectable_rows:
        return
    state.selection = len(state.data.selectable_rows) - 1 if to_end else 0


def page_selection(state: AppState, delta: int, term_h: int) -> None:
    amount = max(1, (term_h - 4) // 2)
    move_selection(state, delta * amount)


def jump_head(state: AppState) -> None:
    if not state.data.head_hash:
        return
    for si, ri in enumerate(state.data.selectable_rows):
        r = state.data.rows[ri]
        if r.kind == "commit" and r.commit == state.data.head_hash:
            state.selection = si
            return


def cycle_label(state: AppState, delta: int) -> None:
    row = current_selected_row(state)
    if not row or row.kind != "commit" or not row.commit:
        return
    labels = state.data.labels_by_commit.get(row.commit, [])
    if len(labels) <= 1:
        return
    idx = state.label_indices.get(row.commit, 0)
    idx = max(0, min(len(labels) - 1, idx + delta))
    state.label_indices[row.commit] = idx


def jump_labeled(state: AppState, delta: int) -> None:
    if not state.data.selectable_rows:
        return
    start = state.selection + delta
    rng = range(start, len(state.data.selectable_rows)) if delta > 0 else range(start, -1, -1)
    for si in rng:
        r = state.data.rows[state.data.selectable_rows[si]]
        if r.kind == "commit" and r.commit and state.data.labels_by_commit.get(r.commit):
            state.selection = si
            return


def branch_target_commit(state: AppState) -> Optional[str]:
    row = current_selected_row(state)
    if row and row.kind == "commit":
        return row.commit
    return None


def create_branch(state: AppState, name: str) -> None:
    commit = branch_target_commit(state)
    if not commit:
        state.mode = "normal"
        return
    if not name.strip():
        state.mode = "normal"
        return
    cp = run_git(["branch", name.strip(), commit], cwd=state.data.root)
    if cp.returncode != 0:
        set_error(state, f"Failed to create branch '{name.strip()}'")
        return
    state.mode = "normal"
    clear_status(state)
    reload_state(state)


def delete_selected_branch(state: AppState) -> None:
    lab = selected_label(state)
    if not lab or lab.kind == "remote" or not lab.local:
        return
    cur = state.data.current_branch
    if cur == lab.local:
        return
    state.confirm_branch = lab.local
    state.mode = "confirm_delete"


def confirm_delete(state: AppState) -> None:
    name = state.confirm_branch
    if not name:
        state.mode = "normal"
        return
    cp = run_git(["branch", "-D", name], cwd=state.data.root)
    if cp.returncode != 0:
        set_error(state, f"Failed to delete branch '{name}'")
        return
    state.confirm_branch = ""
    state.mode = "normal"
    clear_status(state)
    reload_state(state)


def checkout_selected(state: AppState) -> None:
    row = current_selected_row(state)
    if not row or row.kind != "commit" or not row.commit:
        return
    lab = selected_label(state, row)
    root = state.data.root
    cp: subprocess.CompletedProcess
    if lab and lab.kind in ("local", "tracking") and lab.local:
        cp = run_git(["checkout", lab.local], cwd=root)
    elif lab and lab.kind == "remote" and lab.remote and lab.local:
        exists = lab.local in state.data.local_branches
        if exists:
            cp1 = run_git(["branch", "-f", lab.local, lab.remote], cwd=root)
            if cp1.returncode != 0:
                cp = cp1
            else:
                cp = run_git(["checkout", lab.local], cwd=root)
        else:
            cp = run_git(["checkout", "-b", lab.local, "--track", lab.remote], cwd=root)
    else:
        cp = run_git(["checkout", "--detach", row.commit], cwd=root)
    if cp.returncode != 0:
        err = first_error_line(cp.stderr) or "checkout failed"
        set_error(state, f"Checkout failed: {err}")
        return
    clear_status(state)
    reload_state(state)


def fetch_origin(state: AppState) -> None:
    cp = run_git(["fetch", "origin"], cwd=state.data.root, timeout=60)
    if cp.returncode == 0:
        reload_state(state)
        state.status_message = "Fetched from origin"
        state.status_error = False
        state.mode = "normal"
    else:
        err = first_error_line(cp.stderr) or "git fetch failed"
        set_error(state, f"git fetch failed: {err}")


def all_search_labels(state: AppState) -> List[Label]:
    labels: List[Label] = []
    # In display order: labels on visible commits first, then any stragglers.
    seen = set()
    for r in state.data.rows:
        if r.kind == "commit" and r.commit:
            for lab in state.data.labels_by_commit.get(r.commit, []):
                key = (lab.display, lab.commit)
                if key not in seen:
                    labels.append(lab); seen.add(key)
    for commit, labs in state.data.labels_by_commit.items():
        for lab in labs:
            key = (lab.display, lab.commit)
            if key not in seen:
                labels.append(lab); seen.add(key)
    return labels


def fuzzy_match(q: str, s: str) -> bool:
    q = q.lower()
    s = s.lower()
    if q in s:
        return True
    pos = 0
    for ch in q:
        pos = s.find(ch, pos)
        if pos < 0:
            return False
        pos += 1
    return True


def update_search(state: AppState) -> None:
    q = state.input_text.strip()
    if not q:
        state.search_results = []
        state.search_selected = 0
        return
    res = [lab for lab in all_search_labels(state) if fuzzy_match(q, lab.display)]
    state.search_results = res[:20]
    state.search_selected = max(0, min(state.search_selected, len(state.search_results) - 1))


def accept_search(state: AppState) -> None:
    if not state.input_text:
        state.mode = "normal"
        return
    if not state.search_results:
        return
    lab = state.search_results[state.search_selected]
    for si, ri in enumerate(state.data.selectable_rows):
        r = state.data.rows[ri]
        if r.kind == "commit" and r.commit == lab.commit:
            state.selection = si
            labs = state.data.labels_by_commit.get(lab.commit, [])
            for i, l in enumerate(labs):
                if l.display == lab.display:
                    state.label_indices[lab.commit] = i
                    break
            break
    state.mode = "normal"
    state.input_text = ""
    state.search_results = []


# ----------------------------- input handling -------------------------------

def read_key(fd: int, timeout: float = 0.1) -> Optional[str]:
    r, _, _ = select.select([fd], [], [], timeout)
    if not r:
        return None
    try:
        b = os.read(fd, 1)
    except OSError:
        return None
    if not b:
        return None
    if b == b"\x1b":
        # Collect the remainder of an escape sequence if present.
        seq = b
        time.sleep(0.003)
        while True:
            rr, _, _ = select.select([fd], [], [], 0)
            if not rr:
                break
            chunk = os.read(fd, 1)
            if not chunk:
                break
            seq += chunk
            if (65 <= chunk[0] <= 90) or chunk in (b"~",):
                break
        maps = {
            b"\x1b[A": "UP", b"\x1b[B": "DOWN", b"\x1b[C": "RIGHT", b"\x1b[D": "LEFT",
            b"\x1b[H": "HOME", b"\x1b[F": "END", b"\x1bOH": "HOME", b"\x1bOF": "END",
            b"\x1b[1~": "HOME", b"\x1b[4~": "END", b"\x1b[7~": "HOME", b"\x1b[8~": "END",
            b"\x1b[Z": "SHIFT_TAB",
        }
        return maps.get(seq, "ESC")
    if b in (b"\r",):
        return "ENTER"
    if b == b"\n":
        return "CTRL_J"
    if b in (b"\x7f", b"\b"):
        return "BACKSPACE"
    if b == b"\t":
        return "TAB"
    if b == b"\x04":
        return "CTRL_D"
    if b == b"\x15":
        return "CTRL_U"
    if b == b"\x03":
        raise KeyboardInterrupt
    try:
        return b.decode("utf-8")
    except UnicodeDecodeError:
        return None


def is_printable_key(k: str) -> bool:
    return len(k) == 1 and (ord(k) >= 32) and k != "\x7f"


def handle_key(state: AppState, key: str, term_h: int) -> bool:
    """Return False to quit."""
    if state.mode == "error":
        if key in ("ESC", "ENTER", "CTRL_J"):
            clear_status(state)
            return True
        if key == "q":
            return False
        return True

    if state.mode == "help":
        if key in ("ESC", "q", "?"):
            state.mode = "normal"
        return True

    if state.mode == "input_branch":
        if key == "ESC":
            state.mode = "normal"; state.input_text = ""
        elif key in ("ENTER", "CTRL_J"):
            name = state.input_text
            state.input_text = ""
            create_branch(state, name)
        elif key == "BACKSPACE":
            state.input_text = state.input_text[:-1]
        elif is_printable_key(key):
            state.input_text += key
        return True

    if state.mode == "confirm_delete":
        if key in ("y", "Y"):
            confirm_delete(state)
        elif key in ("n", "N", "ESC"):
            state.confirm_branch = ""
            state.mode = "normal"
        return True

    if state.mode == "search":
        if key == "ESC":
            state.mode = "normal"; state.input_text = ""; state.search_results = []
        elif key == "BACKSPACE":
            if state.input_text:
                state.input_text = state.input_text[:-1]
                update_search(state)
            else:
                state.mode = "normal"; state.search_results = []
        elif key in ("ENTER",):
            accept_search(state)
        elif key in ("DOWN", "CTRL_J"):
            if state.search_results:
                state.search_selected = min(len(state.search_results) - 1, state.search_selected + 1)
        elif key in ("UP",):
            if state.search_results:
                state.search_selected = max(0, state.search_selected - 1)
        elif key == "CTRL_U":
            state.input_text = ""; update_search(state)
        elif is_printable_key(key):
            state.input_text += key
            update_search(state)
        return True

    # Normal mode.
    if key in ("q", "ESC"):
        return False
    if key in ("j", "DOWN", "CTRL_J"):
        clear_status(state); move_selection(state, 1)
    elif key in ("k", "UP"):
        clear_status(state); move_selection(state, -1)
    elif key in ("h", "LEFT"):
        cycle_label(state, -1)
    elif key in ("l", "RIGHT"):
        cycle_label(state, 1)
    elif key in ("g", "HOME"):
        jump_selection(state, False)
    elif key in ("G", "END"):
        jump_selection(state, True)
    elif key == "CTRL_D":
        page_selection(state, 1, term_h)
    elif key == "CTRL_U":
        page_selection(state, -1, term_h)
    elif key == "@":
        jump_head(state)
    elif key in ("]", "TAB"):
        jump_labeled(state, 1)
    elif key in ("[", "SHIFT_TAB"):
        jump_labeled(state, -1)
    elif key == "?":
        state.mode = "help"
    elif key == "/":
        state.mode = "search"; state.input_text = ""; state.search_results = []; state.search_selected = 0
    elif key == "b":
        if branch_target_commit(state):
            state.mode = "input_branch"; state.input_text = ""
    elif key == "d":
        delete_selected_branch(state)
    elif key in ("ENTER",):
        checkout_selected(state)
    elif key == "R":
        reload_state(state)
    elif key == "f":
        fetch_origin(state)
    return True


# ----------------------------- main TUI loop --------------------------------

def terminal_size() -> Tuple[int, int]:
    sz = shutil.get_terminal_size((80, 24))
    return sz.columns, sz.lines


def run_tui(root: str) -> int:
    if not (sys.stdin.isatty() and sys.stdout.isatty()):
        eprint("Error: No such device or address (os error 6)")
        return 1
    data = load_repo(root)
    state = AppState(data=data)
    cfg = load_config()
    fd = sys.stdin.fileno()
    old_attrs = termios.tcgetattr(fd)
    running = True
    try:
        tty.setraw(fd)
        sys.stdout.write("\x1b[?1049h\x1b[39m\x1b[49m\x1b[0m\x1b[?25l")
        sys.stdout.flush()
        while running:
            w, h = terminal_size()
            sys.stdout.write("\x1b[H" + render(state, w, h))
            sys.stdout.flush()
            now = time.time()
            if cfg.auto_refresh and now - state.last_refresh >= cfg.refresh_interval and state.mode == "normal":
                reload_state(state)
                state.last_refresh = now
            if cfg.auto_fetch and now - state.last_fetch >= cfg.fetch_interval and state.mode == "normal":
                # Auto-fetch is silent on failure to avoid surprising popups; manual fetch reports errors.
                cp = run_git(["fetch", "origin"], cwd=state.data.root, timeout=60)
                if cp.returncode == 0:
                    reload_state(state)
                state.last_fetch = now
            key = read_key(fd, 0.1)
            if key is not None:
                running = handle_key(state, key, h)
    except KeyboardInterrupt:
        pass
    finally:
        try:
            termios.tcsetattr(fd, termios.TCSADRAIN, old_attrs)
        except Exception:
            pass
        try:
            sys.stdout.write("\x1b[?1049l\x1b[?25h")
            sys.stdout.flush()
        except Exception:
            pass
    return 0


# ----------------------------- entrypoint -----------------------------------

def main() -> int:
    cli = parse_cli(sys.argv[1:])
    if cli is not None:
        return cli
    root = find_repo_root()
    if root is None:
        print_not_repo_error()
        return 1
    return run_tui(root)


if __name__ == "__main__":
    sys.exit(main())
